-- 0073_translate_content_uk.sql
-- Фаза 28: перевод контента программ — украинский (uk).
-- Переведено вручную с русского оригинала (с опорой на вычитанный
-- английский), с терминологией, принятой в залах этой страны. Английские
-- названия упражнений (Hip Thrust, Mountain Climbers…) оставлены как есть.
-- Применять после 0072. Сопоставление — по точному русскому тексту.
-- Безопасно выполнять повторно.

update public.workout_programs p
set title_uk = v.title, description_uk = v.description
from (values
  ('pohudenie-zhenshchiny-doma', 'Схуднення · Жінки · Вдома', 'Схуднення для жінок (вдома) — DonatelleX, річна програма. Обладнання: Гантелі, гумки різної жорсткості, килимок, стійка платформа/сходинка (за можливості)'),
  ('pohudenie-zhenshchiny-zal', 'Схуднення · Жінки · Зал', 'Схуднення для жінок (у залі) — річна програма. Обладнання: Бігова доріжка, еліпс/лижний тренажер, тренажери, гантелі, блоки, килимок'),
  ('nabor-massy-zhenshchiny-doma', 'Набір маси · Жінки · Вдома', 'Набір м''язової маси для жінок (вдома) — річна програма. Обладнання: Гантелі, гумки різної жорсткості, килимок, стійка платформа/сходинка'),
  ('nabor-massy-zhenshchiny-zal', 'Набір маси · Жінки · Зал', 'Набір м''язової маси для жінок (у залі) — річна програма «12 LEVELS». Обладнання: Штанга, гантелі, тренажери (Hip Thrust, Hack Squat, Leg Press, блоки), гумки, гирі, TRX, медбол'),
  ('pohudenie-muzhchiny-doma', 'Схуднення · Чоловіки · Вдома', 'Схуднення для чоловіків (вдома) — річна програма. Обладнання: Гантелі, гумки, турнік (за можливості), стілець/лава, килимок'),
  ('pohudenie-muzhchiny-zal', 'Схуднення · Чоловіки · Зал', 'Схуднення для чоловіків (у залі) — річна програма. Обладнання: Штанга, гантелі, тренажери, блоки, Battle Rope, SkiErg/гребний тренажер, кардіозона (доріжка/еліпс/велотренажер)'),
  ('nabor-massy-muzhchiny-doma', 'Набір маси · Чоловіки · Вдома', 'Набір м''язової маси для чоловіків (вдома) — річна програма. Обладнання: Гантелі, гумки, турнік (за можливості), стілець/лава, килимок'),
  ('nabor-massy-muzhchiny-zal', 'Набір маси · Чоловіки · Зал', 'Набір м''язової маси для чоловіків (у залі) — річна програма. Обладнання: Повний набір залу: штанги, гантелі, тренажери, турнік, канати, TRX, гирі'),
  ('nabor-massy-nachinayushchim', 'Набір маси для початківців', 'Перша програма для чоловіків, які хочуть почати набирати м''язову масу в залі. 7-денний цикл: 4 силові тренування на різні групи м''язів і 3 дні легкого кардіо з пресом. Підходить новачкам — без складної техніки, акцент на обсяг і правильне виконання.')
) as v(slug, title, description)
where p.slug = v.slug;

